-- DRAFT 1.6.4 normal gear through 200: 136 candidate rows, proposed rates.
-- Source: docs/economy/normal-200/drop-policy.json and pilot-source-proposal.csv.
-- Generated by tools/economy/gen_normal_drops.py; edit the inputs, not generated SQL.
-- Pending economy review, client/source/combat proof and release admission. Not auto-enabled.
-- Existing pairs (including quest/card/older drops) are skipped; only inserted pairs are ledgered.
-- Apply/rollback twice is tested locally on disposable MySQL. Reload drops after an approved deployment.
CREATE TABLE IF NOT EXISTS mapleroot_integration_migrations (
  migration_id varchar(100) PRIMARY KEY,
  applied_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS normal_gear_059_rows (
  dropperid int NOT NULL,
  itemid    int NOT NULL,
  PRIMARY KEY (dropperid, itemid)
) ENGINE=InnoDB;

CREATE TEMPORARY TABLE normal_gear_059_new (
  dropperid int NOT NULL, itemid int NOT NULL, minimum_quantity int NOT NULL, maximum_quantity int NOT NULL,
  questid int NOT NULL, chance int NOT NULL, PRIMARY KEY (dropperid, itemid));

-- record only the pairs not already in drop_data (once recorded, a pair stays recorded on a second run)
SELECT n.dropperid, n.itemid FROM normal_gear_059_new n
 WHERE NOT EXISTS (SELECT 1 FROM drop_data d WHERE d.dropperid = n.dropperid AND d.itemid = n.itemid);
SELECT n.dropperid, n.itemid, n.minimum_quantity, n.maximum_quantity, n.questid, n.chance
  FROM normal_gear_059_new n JOIN normal_gear_059_rows r ON r.dropperid = n.dropperid AND r.itemid = n.itemid
 WHERE NOT EXISTS (SELECT 1 FROM drop_data d WHERE d.dropperid = n.dropperid AND d.itemid = n.itemid);

DROP TEMPORARY TABLE normal_gear_059_new;
